2368	// Biases db = Σ_K dY  (column-sum of dY[K,Nout] → [Nout], per output row).
2369	//
2370	// WAS: each CTA strided ALL bias outputs and ran the full Σ_K reduction — i.e. the
2371	// ENTIRE column-sum was recomputed redundantly on ALL ~132 CTAs (the comment called
2372	// it "cheap" — true only when Nout≤3d=384 at the d=128 production width; at the
2373	// d=1024 roofline width Nout reaches 4d=4096 and K=T=65536, so the 132× redundant
2374	// reduction was the DOMINANT grad_asm cost — ~500 ms, eclipsing even the embedding
2375	// scan this task set out to fix; the per-phase profiler (ga.biases sub-timer) made
2376	// it visible). HBM traffic was 132 × Σ_s K_s·Nout_s·2 B ≈ 70 GB.
2377	//
2378	// NOW: SINGLE OWNER per output element across the WHOLE grid. Flatten the 9 specs'
2379	// outputs into one global index space [0, ΣNout) and grid-stride it over all CTAs
2380	// × threads, so each bias output is reduced EXACTLY ONCE and the work is spread
2381	// across the full grid. Traffic collapses to Σ_s K_s·Nout_s·2 B (one pass, ≈ 130×
2382	// less at d=1024). Reads stay COALESCED (consecutive threads → consecutive o on the
2383	// same k → consecutive dY addresses). DETERMINISM: one owner per output + the SAME
2384	// ascending-k fp32 accumulation → bit-identical to the old per-output sum, no atomics.
2385	//
2386	// PORTABLE: the "single-owner grid-stride column-sum" is the general fix for any
2387	// bias/reduction-to-a-vector that a megakernel was recomputing per-CTA; vit/mamba
2388	// bias grads (same db = Σ_K dY shape) reuse this verbatim.
2389	__device__ __forceinline__ void dectc_dw_biases(
2390	        const DecDwSpec spec[9], float* __restrict__ grad, int cta, int nCTA) {
2391	    // exclusive prefix of Nout across the 9 specs → total bias-output count.
2392	    int pre[10];
2393	    pre[0] = 0;
2394	    #pragma unroll
2395	    for (int s = 0; s < 9; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
2396	    const int total = pre[9];
2397	    const int stride = nCTA * blockDim.x;
2398	    for (int go = cta * blockDim.x + threadIdx.x; go < total; go += stride) {
2399	        // decode global output index → (spec s, local row o). 9 specs → linear scan.
2400	        int s = 0;
2401	        #pragma unroll
2402	        for (int t = 0; t < 9; ++t) if (go >= pre[t + 1]) s = t + 1;
2403	        const DecDwSpec& sp = spec[s];
2404	        const int o = go - pre[s];
2405	        float accv = 0.0f;
2406	        for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
2407	        grad[sp.bias_off + o] = accv;
2408	    }
2409	}
